class Intake(HTMLParser):
    def __init__(self):
        super().__init__(); self.forms=[]; self.text=[]; self.hidden=None
    def handle_starttag(self,tag,attrs):
        if tag in ('script','style'): self.hidden=tag
        if tag=='a':
            href=dict(attrs).get('href','')
            if href.lower().startswith('mailto:'):
                query=parse_qs(urlsplit(href).query,keep_blank_values=True)
                self.forms.append({key:query.get(key,[]) for key in ('subject','body')})
    def handle_endtag(self,tag):
        if tag==self.hidden: self.hidden=None
    def handle_data(self,data):
        if self.hidden is None and data.strip(): self.text.append(' '.join(data.split()))
